{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "New Jersey Anti-Eviction Act Good Cause Eviction Requirement",
      "requirement": "Landlords cannot remove a residential tenant except by establishing one of the statutory good-cause grounds specified by law.",
      "requirement_es": "Los arrendadores no pueden desalojar a un inquilino residencial excepto si demuestran una de las causas justificadas establecidas por la ley.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Owner-occupied premises with not more than two rental units",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "owner-occupied premises"
              },
              {
                "field": "units",
                "operator": "<=",
                "value": 3,
                "note": "not more than two rental units"
              }
            ]
          }
        },
        {
          "description": "Hotel, motel or other guest house rented to transient guests or seasonal tenants",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Dwelling unit held in trust or occupied by an immediate family member of the owner with a developmental disability",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2013-07-01",
      "superseded_date": null,
      "status": "enacted",
